  'Abrir = válido': { de: 'Öffnen = gültig' },
  'Abrir la ruta del documento (flecha de estado)': { de: 'Den Belegweg öffnen (Statuspfeil)' },
  'Abrir sin control destruye el cierre.': { en: 'Opening without control destroys the close.', de: 'Unkontrolliertes Öffnen zerstört den Abschluss.' },
  'Abrir y listo': { de: 'Öffnen und fertig' },
