  'Activo 10.000, vida 5 años, lineal. ¿Depreciación anual y asiento?': { en: 'Asset 10,000, 5-year life, straight-line. Annual depreciation and entry?', de: 'Anlage 10.000, Nutzungsdauer 5 Jahre, linear. Jahresabschreibung und Buchung?' },
  'Activo: alta → depreciación → baja': { de: 'Anlage: Zugang → Abschreibung → Abgang' },
  'Activos': { en: 'Fixed assets', de: 'Anlagevermögen' },
